// checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { describe, it, expect, vi } from 'vitest';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

describe('Checkout Component - Liability Assessment', () => {
  const user = userEvent.setup();

  describe('Happy Path - Documented Compliance', () => {
    it('completes full checkout flow with valid inputs', async () => {
      render(<Checkout cartItems={mockCart} />);

      // Shipping step
      await user.type(screen.getByRole('textbox', { name: /address/i }), '123 Main St');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByRole('textbox', { name: /card number/i }), '4111111111111111');
      await user.type(screen.getByRole('textbox', { name: /expiry/i }), '12/28');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Confirmation
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('heading', { name: /order confirmed/i })).toBeInTheDocument();
      });
    });
  });

  describe('Validation - Reducing User Error Liability', () => {
    it('displays inline error for invalid email format', async () => {
      render(<Checkout cartItems={mockCart} />);

      await user.type(screen.getByRole('textbox', { name: /email/i }), 'not-an-email');
      await user.tab();

      expect(screen.getByRole('alert')).toHaveTextContent(/valid email/i);
    });

    it('rejects expired credit cards', async () => {
      render(<Checkout cartItems={mockCart} />);
      // Navigate to payment...

      await user.type(screen.getByRole('textbox', { name: /expiry/i }), '01/20');
      await user.tab();

      expect(screen.getByRole('alert')).toHaveTextContent(/expired/i);
    });
  });

  describe('Error Recovery - Limiting Damages', () => {
    it('allows retry after payment failure without re-entering data', async () => {
      const failOnce = vi.fn()
        .mockRejectedValueOnce(new Error('Declined'))
        .mockResolvedValueOnce({ orderId: '123' });

      render(<Checkout onSubmit={failOnce} cartItems={mockCart} />);
      // Complete form, submit...

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/payment declined/i);
      });

      await user.click(screen.getByRole('button', { name: /try again/i }));

      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
    });
  });

  describe('Accessibility - ADA Compliance', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout cartItems={mockCart} />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('announces errors to screen readers', async () => {
      render(<Checkout cartItems={mockCart} />);
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveAttribute('aria-live', 'polite');
    });
  });

  describe('Edge Cases - Hostile Acquisition Scenarios', () => {
    it('handles empty cart gracefully', () => {
      render(<Checkout cartItems={[]} />);
      expect(screen.getByText(/cart is empty/i)).toBeInTheDocument();
    });

    it('prevents double submission during loading', async () => {
      const onSubmit = vi.fn(() => new Promise(() => {}));
      render(<Checkout onSubmit={onSubmit} cartItems={mockCart} />);

      await user.click(screen.getByRole('button', { name: /place order/i }));
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(onSubmit).toHaveBeenCalledTimes(1);
    });
  });
});
